import{_ as t,o as a,c as s,a3 as r}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"Data between steps","description":"Use the results of previous steps in later steps of a Flow.","frontmatter":{"title":"Data between steps","description":"Use the results of previous steps in later steps of a Flow."},"headers":[],"relativePath":"en/flows/daten-zwischen-schritten.md","filePath":"en/flows/daten-zwischen-schritten.md","lastUpdated":1787319236000}'),n={name:"en/flows/daten-zwischen-schritten.md"};function i(o,e,l,d,h,p){return a(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="data-between-steps" tabindex="-1">Data between steps <a class="header-anchor" href="#data-between-steps" aria-label="Permalink to &quot;Data between steps&quot;">​</a></h1><p>Every step of a Flow can access the results of the previous ones. That&#39;s the basic principle: the <a href="/en/flows/trigger">trigger</a> delivers data, the first action works with it, the second uses its result.</p><h2 id="inserting-values" tabindex="-1">Inserting values <a class="header-anchor" href="#inserting-values" aria-label="Permalink to &quot;Inserting values&quot;">​</a></h2><p>In a step&#39;s settings, <strong>Use values from previous steps</strong> leads to the selection of available data. A click places the value at the cursor; alternatively, drag it to the desired spot in the text field.</p><p>An inserted value appears as a colored chip. Clicking it opens the <a href="/en/apptivescript/editor">expression editor</a> — there the value can be processed further, for example converted or given a fallback value.</p><div class="tip custom-block"><p class="custom-block-title">Mixing fixed text and values</p><p>You don&#39;t have to choose. An email subject can read: <code>Your registration for </code> followed by the <code>Event</code> field from the trigger. This applies to recipient, subject, body, and most other input fields.</p></div><div class="tip custom-block"><p class="custom-block-title">Keyboard shortcut in the JavaScript step and the HTML block</p><p>These two have a code editor instead of chips. There, <strong>Ctrl + Space</strong> inserts Grid fields:</p><blockquote><p><em>Press Ctrl + Space to insert Grid fields</em></p></blockquote><p>→ <a href="/en/apptivescript/editor#grid-fields-in-the-html-block-and-the-javascript-step">The expression editor</a></p></div><h2 id="what-the-trigger-delivers" tabindex="-1">What the trigger delivers <a class="header-anchor" href="#what-the-trigger-delivers" aria-label="Permalink to &quot;What the trigger delivers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Trigger</th><th>Available data</th></tr></thead><tbody><tr><td><strong>New entry</strong></td><td>The newly created entry with all fields</td></tr><tr><td><strong>Entry was changed</strong></td><td>The changed entry with all fields</td></tr><tr><td><strong>Entry via form</strong></td><td>The created entry</td></tr><tr><td><strong>Entry changed via form</strong></td><td>The changed entry</td></tr><tr><td><strong>Webhook</strong></td><td>The submitted JSON data</td></tr><tr><td><strong>Show page</strong></td><td>The values entered on the page</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">All fields are available</p><p>Even fields that weren&#39;t asked for on the triggering form are available — the Flow gets the complete entry, not just the form inputs.</p></div><h2 id="what-actions-deliver" tabindex="-1">What actions deliver <a class="header-anchor" href="#what-actions-deliver" aria-label="Permalink to &quot;What actions deliver&quot;">​</a></h2><p>Every action passes on a result that later steps can use:</p><table tabindex="0"><thead><tr><th>Action</th><th>Result</th></tr></thead><tbody><tr><td><strong>Load all entries</strong></td><td>A list of entries</td></tr><tr><td><strong>Create entry</strong></td><td>The newly created entry</td></tr><tr><td><strong>QR Code</strong></td><td>The generated code</td></tr><tr><td><strong>PDF to text</strong></td><td>The extracted text</td></tr><tr><td><strong>Import CSV file</strong></td><td>The read-in rows</td></tr><tr><td><strong>JavaScript</strong></td><td>The return value of the code</td></tr><tr><td><strong>Create link to page</strong></td><td>A link to the running instance</td></tr><tr><td><strong>Prefilled form link</strong></td><td>An editing link</td></tr></tbody></table><h2 id="lists-need-parallel" tabindex="-1">Lists need &quot;Parallel&quot; <a class="header-anchor" href="#lists-need-parallel" aria-label="Permalink to &quot;Lists need &quot;Parallel&quot;&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">A list is not yet a repetition</p><p>If a step delivers a <strong>list</strong> — such as <em>Load all entries</em> — the following steps still only run <strong>once</strong>.</p><p>Only the <strong>Parallel</strong> helper turns it into individual runs per element. → <a href="/en/flows/router-und-parallel">Router and Parallel</a></p></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Load all entries          →  list</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Parallel                   →  once per element</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Email                       →  a single entry is available here</span></span></code></pre></div><p>Inside <em>Parallel</em>, you refer to the <strong>current element</strong>, not the whole list anymore.</p><p>With <strong>Merge runs</strong>, the parallel section ends: after that the Flow runs once again, and you no longer refer to a single element. → <a href="/en/flows/router-und-parallel">Router and Parallel</a></p><h2 id="values-from-the-javascript-step" tabindex="-1">Values from the JavaScript step <a class="header-anchor" href="#values-from-the-javascript-step" aria-label="Permalink to &quot;Values from the JavaScript step&quot;">​</a></h2><p>The <a href="/en/flows/aktionen">JavaScript step</a> receives the previous step&#39;s data as <code>input</code> and passes it on with <code>return</code>:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> data</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> input</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data.status </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;processed&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> data</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">For transformations no step covers</p><p>If an outside system expects a specific format, or values need to be converted, this is the way to do it — without running a service of your own.</p></div><h2 id="data-from-pages" tabindex="-1">Data from pages <a class="header-anchor" href="#data-from-pages" aria-label="Permalink to &quot;Data from pages&quot;">​</a></h2><p>If a Flow shows a <a href="/en/flows/seiten-in-flows">page</a>, the values entered there become available afterward. Access happens via the <strong>key</strong> of the respective input block.</p><div class="warning custom-block"><p class="custom-block-title">Set the key before referencing it</p><p>If you change the key afterward, existing references point to nothing — without an error message. → <a href="/en/seiten/eingabebloecke">Input blocks</a></p></div><p>For <a href="/en/seiten/html-bloecke">HTML blocks with form fields</a>, an additional rule applies: input fields without a <code>name</code> or <code>id</code> attribute are <strong>not</strong> passed through.</p><h2 id="when-values-arrive-empty" tabindex="-1">When values arrive empty <a class="header-anchor" href="#when-values-arrive-empty" aria-label="Permalink to &quot;When values arrive empty&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th></tr></thead><tbody><tr><td>Empty value in the email</td><td>The field wasn&#39;t filled in the entry</td></tr><tr><td>Reference to a later step</td><td>Only previous steps are available</td></tr><tr><td>After a Router</td><td>The other branch was taken, its data is missing</td></tr><tr><td>After a page</td><td>The key doesn&#39;t match, or was changed</td></tr><tr><td>From an HTML block</td><td><code>name</code> or <code>id</code> attribute is missing</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Look instead of guess</p><p>Via <strong>Show details</strong> on a step, you can see its actual input and output data from a real run. That clears up almost every &quot;why is this empty&quot; question faster than thinking about it.</p><p>→ <a href="/en/flows/testen">Testing Flows</a></p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/flows/aktionen">Actions</a></li><li><a href="/en/flows/router-und-parallel">Router and Parallel</a></li><li><a href="/en/flows/testen">Testing Flows</a></li></ul>`,31)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
